    /// <summary>Cars with NO verified exact detailed model AND no
    /// Kenney final look: the 8 fictional starters (0-7 except 5,
    /// which has the detailed Khronos CarConcept) plus 30 Maseratii
    /// MC20. These cars use the improved procedural body
    /// (CarVisuals.Rebuild) instead of a Kenney stand-in — the user
    /// rejected Kenney low-poly as the final look, and no detailed
    /// Sketchfab model exists for these cars, so the procedural path
    /// IS their final look. When a detailed model lands for one of
    /// them, remove its index here AND add it to DetailedCars.
    /// CarVisuals.TryBuildKenneyCar consults this set; Resolve() is
    /// untouched (meet / showcase still fall back to Kenney there).</summary>
    public static readonly System.Collections.Generic.HashSet<int> ProceduralOnlyCars =
        new System.Collections.Generic.HashSet<int>
        {
            0, // City Sprint — fictional starter, no detailed model
            1, // Street GT — fictional starter, no detailed model
            2, // Desert Fox — fictional starter, no detailed model
            3, // Night Hawk — fictional starter, no detailed model
            4, // Horizon R — fictional starter, no detailed model
            6, // Apex GT — fictional starter, no detailed model
            7, // Horizon X — fictional starter, no detailed model
            30, // Maseratii MC20 — no verified exact detailed model
        };

    /// <summary>True when a car must use the procedural body (no
    /// detailed model, Kenney rejected as its final look).</summary>
    public static bool IsProceduralOnly(int index)
    {
        return ProceduralOnlyCars.Contains(index);
    }

    /// <summary>Indices with a verified exact free Sketchfab model waiting
    /// for the account download (ModelSources.md §4A) — detailed-model
    /// priority order. The five ModVision-credit cars (18, 20, 23, 42, 44)
    /// follow once their Sketchfab URLs are confirmed.</summary>
    public static readonly int[] SketchfabPriority = new int[]
        { 38, 27, 33, 39, 14, 28, 29, 32, 17, 41, 51 };

    /// <summary>Resources path of the per-car model hook (no spaces in
    /// the file name — the same convention CarMeetManager and
    /// ShowcaseGarageManager already use). This path holds the Kenney
    /// stand-in prefab NOW (built by BuildCarPrefabs) and the detailed
    /// Sketchfab model LATER (the pipeline agent replaces the prefab
    /// content at this same path — no code change needed anywhere).</summary>
    public static string DetailedPathForCar(int index)
    {
        if (index < 0 || index >= CarSelection.Cars.Length) return null;
        return "Models/Cars/" + CarSelection.Cars[index].carName.Replace(" ", "");
    }

