    /// <summary>Resolve the model for a car. Returns the prefab to
    /// instantiate and whether it is a detailed (Sketchfab) model — a
    /// detailed model carries its own PBR materials and wheels, so the
    /// caller must NOT apply the Kenney atlas paint or reparent its
    /// wheels; a Kenney stand-in gets the atlas paint + wheel treatment.
    /// Never returns null: the Kenney stand-in is the guaranteed fallback
    /// (if even that is missing, "sedan-sports" is used).</summary>
    public static GameObject Resolve(int index, out bool detailed)
    {
        detailed = false;
        if (index < 0 || index >= CarSelection.Cars.Length) index = 1;
        if (DetailedCars.Contains(index))
        {
            GameObject d = KenneyModels.LoadPrefab(DetailedPathForCar(index));
            if (d != null)
            {
                detailed = true;
                return d;
            }
            Debug.LogWarning("[CarModelMap] detailed model listed for car " + index
                + " but not found at " + DetailedPathForCar(index) + " — using Kenney stand-in");
        }
        if (index < 0 || index >= KenneyStyleForCar.Length) index = 1;
        GameObject k = KenneyModels.LoadPrefab("Models/Kenney/CarKit/" + KenneyStyleForCar[index]);
        if (k == null) k = KenneyModels.LoadPrefab("Models/Kenney/CarKit/sedan-sports");
        return k;
    }

    /// <summary>True when the resolved model for a car is a detailed
    /// Sketchfab model (not a Kenney stand-in).</summary>
    public static bool IsDetailed(int index)
    {
        bool detailed;
        Resolve(index, out detailed);
        return detailed;
    }
}
